 /*
 Objetivo de este codigo es hacer un semaforo con 3 leds, verde, amarillo y rojo, usando el microcontrolador STM32F411RE
 */

#include <stdint.h>
#include <stm32f4xx.h>

uint8_t estado_actual = 0;

int main(void)
{
    /*
    * Paso 1: habilitar el reloj del GPIOB (RCC_AHB1ENR)
    *Manual de referencia: RM0383, sección 6.3.9
    */
    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOBEN;
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;

    /*
    Paso 2: configurar el pin PB8, PB9, PB6 como salida PUSH-PULL, VELOCIDAD BAJA, SIN PULL-UP/PULL-DOWN Y GPIOB.ODR=0 
    y el PDR no se toca por que ponemos una resistencia de 10k en el pin del led
    */

    /*
    Verde
    */
    GPIOB->MODER &= ~(GPIO_MODER_MODE8); // Limpiar los bits de modo para PB8
    GPIOB->MODER |= (GPIO_MODER_MODE8_0); // Configurar PB8 como salida (01)
    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT8); // Configurar PB8 como push-pull (0)
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED8); // Configurar PB8 como velocidad baja (00)
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD8); // Configurar PB8 sin pull-up/pull-down (00)
    GPIOB-> ODR &= ~(GPIO_ODR_OD8); // Inicializar PB8 en bajo (0)

    /*
     Amarillo
     */

    GPIOB->MODER &= ~(GPIO_MODER_MODE9); // Limpiar los bits de modo para PB9
    GPIOB->MODER |= (GPIO_MODER_MODE9_0); // Configurar PB9 como salida (01)
    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT9); // Configurar PB9 como push-pull (0)
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED9); // Configurar PB9 como velocidad baja (00)
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD9); // Configurar PB9 sin pull-up/pull-down (00)
    GPIOB-> ODR &= ~(GPIO_ODR_OD9); // Inicializar PB9 en bajo (0)

    /*
     Rojo
     */

    GPIOB->MODER &= ~(GPIO_MODER_MODE6); // Limpiar los bits de modo para PB6
    GPIOB->MODER |= (GPIO_MODER_MODE6_0); // Configurar PB6 como salida (01)
    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT6); // Configurar PB6 como push-pull (0)
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED6); // Configurar PB6 como velocidad baja (00)
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD6); // Configurar PB6 sin pull-up/pull-down (00)
    GPIOB-> ODR &= ~(GPIO_ODR_OD6); // Inicializar PB6 en bajo (0)

    /*
    Paso 3: Configurar el SysTick para generar interrupciones cada 1000ms o 1 segundo.
    Core-Cortex M4 documento.
    */

    SysTick->LOAD = 16000000 - 1; // Cargar el valor de recarga para 1 segundo (16 MHz)
    SysTick->VAL = 0; // Limpiar el valor actual del contador
    SysTick->CTRL &= ~(SysTick_CTRL_TICKINT_Msk); // Deshabilitar la interrupción del SysTick
    SysTick->CTRL |= (SysTick_CTRL_CLKSOURCE_Msk); // Seleccionar la fuente de reloj del procesador (HCLK)
    SysTick->CTRL &= ~(SysTick_CTRL_ENABLE_Msk); // Deshabilitar el contador del SysTick
    SysTick->CTRL |= (SysTick_CTRL_ENABLE_Msk); // Habilitar el contador del SysTick
    
    /*
    *Bucle principal del programa superloop
    */

	while(1){
        /*El bit COUNTFLAG del registro de control del SysTick se establece en 1 cuando el contador llega a cero, 
        indicando que ha transcurrido el tiempo especificado.
        Se limpia automáticamente al leer el registro de control del SysTick.
        */

        if(SysTick->CTRL & SysTick_CTRL_COUNTFLAG_Msk) {
            // Actualizar los LEDs según el estado actual
            switch (estado_actual) {
                case 0: // Verde
                    GPIOB->ODR |= GPIO_ODR_OD8; // Encender LED verde
                    GPIOB->ODR &= ~GPIO_ODR_OD9; // Apagar LED amarillo
                    GPIOB->ODR &= ~GPIO_ODR_OD6; // Apagar LED rojo
                    estado_actual ++; // Cambiar al siguiente estado
                    break;
                case 1: // Amarillo
                    GPIOB->ODR &= ~GPIO_ODR_OD8; // Apagar LED verde
                    GPIOB->ODR |= GPIO_ODR_OD9; // Encender LED amarillo
                    GPIOB->ODR &= ~GPIO_ODR_OD6; // Apagar LED rojo
                    estado_actual ++; // Cambiar al siguiente estado
                    break;
                case 2: // Rojo
                    GPIOB->ODR &= ~GPIO_ODR_OD8; // Apagar LED verde
                    GPIOB->ODR &= ~GPIO_ODR_OD9; // Apagar LED amarillo
                    GPIOB->ODR |= GPIO_ODR_OD6; // Encender LED rojo
                    estado_actual = 0; // Volver al primer estado   
                    break;

                    default:
                    estado_actual = 0; // Reiniciar el estado en caso de un valor inesperado
                    break;
            }
        }
    }

}
